                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IModelGetter ModelFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return ModelFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.MODF:
                {
                    _FlagsLocation = (stream.Position - offset);
                    return (int)Model_FieldIndex.Flags;
                }
                case RecordTypeInts.ENLM:
                {
                    _ENLMLocation = (stream.Position - offset);
                    return (int)Model_FieldIndex.ENLM;
                }
                case RecordTypeInts.XFLG:
                {
                    _XFLGLocation = (stream.Position - offset);
                    return (int)Model_FieldIndex.XFLG;
                }
                case RecordTypeInts.ENLT:
                {
                    _ENLTLocation = (stream.Position - offset);
                    return (int)Model_FieldIndex.ENLT;
                }
                case RecordTypeInts.ENLS:
                {
                    _ENLSLocation = (stream.Position - offset);
                    return (int)Model_FieldIndex.ENLS;
                }
                case RecordTypeInts.AUUV:
                {
                    _AUUVLocation = (stream.Position - offset);
                    return (int)Model_FieldIndex.AUUV;
                }
                case RecordTypeInts.MODD:
                {
                    _MODDLocation = (stream.Position - offset);
                    return (int)Model_FieldIndex.MODD;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
